training_cutoff_knowledge = {
    "capital of france": "Paris",  # stable, general knowledge
}

# private, current information never seen during training
live_document_store = {
    "current company revenue": "The company reported $42 million in revenue this quarter.",
}

def answer_without_rag(query):
    # the frozen knowledge problem: only knows what was in training data
    key = query.lower()
    return training_cutoff_knowledge.get(key, "I don't have information about that.")

def answer_with_rag(query, document_store):
    # retrieval grounds the answer in fresh context
    key = query.lower()
    retrieved = document_store.get(key)
    if retrieved:
        return f"Based on retrieved context: {retrieved}"
    return training_cutoff_knowledge.get(key, "I don't have information about that.")

query = "current company revenue"
print(f"Query: {query}")
print(f"Without RAG: {answer_without_rag(query)}")
print(f"With RAG: {answer_with_rag(query, live_document_store)}")
